    fn entry(start: &str, duration: i64, billable: bool, stop: bool) -> TimeEntry {
        let start = Utc.datetime_from_str(start, "%Y-%m-%dT%H:%M:%SZ").unwrap();
        TimeEntry {
            id: 1,
            description: String::new(),
            start,
            stop: stop.then_some(start + chrono::Duration::seconds(duration)),
            duration,
            billable,
            workspace_id: 1,
            tags: vec![],
            project: None,
            task: None,
            created_with: None,
        }
    }

    #[test]
    fn groups_billable_stopped_entries_by_utc_monday() {
        let totals = weekly_totals(&[
            entry("2026-03-08T23:30:00Z", 10, true, true),
            entry("2026-03-09T00:30:00Z", 20, true, true),
            entry("2026-03-10T12:00:00Z", 30, false, true),
            entry("2026-03-16T12:00:00Z", 40, true, false),
