        assert_eq!(
            totals.get(&NaiveDate::from_ymd_opt(2026, 3, 2).unwrap()),
            Some(&10)
        );
        assert_eq!(
            totals.get(&NaiveDate::from_ymd_opt(2026, 3, 9).unwrap()),
            Some(&20)
        );
        assert!(!totals.contains_key(&NaiveDate::from_ymd_opt(2026, 3, 16).unwrap()));
    }
}

