        let totals = weekly_totals(&entries);

        if totals.is_empty() {
            println!("(no data)");
            return Ok(());
        }

        let total: i64 = totals.values().sum();
        for (monday, seconds) in totals {
            println!("{}  {seconds}s", monday.format("%Y-%m-%d"));
        }
        println!("Total  {total}s");
        Ok(())
    }
}

