            entry("2026-03-16T12:00:00Z", 40, true, false),
        ]);

        assert_eq!(
            totals.get(&NaiveDate::from_ymd_opt(2026, 3, 2).unwrap()),
            Some(&10)
        );
        assert_eq!(
